import {openingPage} from './opening.mjs';
import {mountOnboardingMotion,resetOnboardingMotion} from './personal-onboarding-motion.mjs?v=flower25';
export function createPersonalOnboarding(root,onFinish){
let active=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flow=[0,1,2,4,5,7,8,9,10,11,12,13,14,15];
let acknowledgement='';
let step=new URLSearchParams(location.search).get('onboarding')==='reminder'?14:0,answers={name:'',comparison:'',intention:'',more:'',season:[],children:'',familiarity:'',heart:[],people:[],names:'',pace:'',reminder:false,time:'08:00'};
const data={
5:{title:'Which do you spend more time on?',sub:'Be honest…' ,key:'comparison',options:['Social media','The Bible','About the same'],foot:'No judgment. Just a place to begin.',art:'magnifier'},
7:{title:'What season of life are you in?',sub:'Life doesn’t fit in one box. Choose all that feel true.',key:'season',multi:true,options:['Single','Dating','Married','Motherhood','Separated or divorced','Prefer not to say'],foot:'You don’t have to have it all figured out.',art:'growth-vase'},
8:{title:'How familiar does the Bible feel?',sub:'We’ll meet you at your starting point.',key:'familiarity',options:['Just starting','I know a little','I read regularly'],foot:'No test. No catching up.',art:'wisdom-scroll'},
9:{title:'What’s on your heart lately?',sub:'More than one feeling can be true. Choose up to three.',key:'heart',multi:true,options:['Peace','Purpose','Faith','Relationships','Identity','Anxiety','Gratitude','Hope','Wisdom'],foot:'Bring the whole of you.',art:'hope-nest'},
12:{title:'How much time can you give to God each day?',sub:'A small moment is a beautiful beginning.',key:'pace',options:['2 minutes','5 minutes','10 minutes','No set goal'],foot:'Your pace. You can change it anytime.',art:'quiet-window'}
};
const btn=(label='Continue',action='next')=>`<button class="primary" data-action="${action}">${label}<span aria-hidden="true"> →</span></button>`;
const field=(key,label,placeholder,type='text')=>`<label class="field">${label}<input name="${key}" type="${type}" maxlength="${key==='name'?24:60}" value="${esc(answers[key])}" placeholder="${placeholder}" ${key==='name'?'autocomplete="given-name" autocapitalize="words"':''}></label>`;
const art=name=>`<img class="question-art" src="illustration-pack/${name}.png" alt="">`;
function prayer(){
const n=answers.name.trim()||'Your daughter';
const seasons={Single:'Walk with her as she builds her life.',Dating:'Guide her heart in love.',Married:'Nurture tenderness in her marriage.',Motherhood:'Hold her as she cares for her children.','Separated or divorced':'Be near as she finds her footing after separation.'};
const season=answers.season.includes('Motherhood')?'Hold her as she cares for her children.':answers.season.includes('Separated or divorced')?'Be near as she finds her footing after separation.':answers.season.map(x=>seasons[x]).filter(Boolean)[0]||'Meet her right where she is.';
const needs={Peace:'peace for her heart',Purpose:'direction for her next step',Faith:'trust amid her questions',Relationships:'kindness in her relationships',Identity:'confidence in her worth',Anxiety:'calm in anxious moments',Gratitude:'eyes for everyday goodness',Hope:'hope for tomorrow',Wisdom:'wisdom for her choices'};
const people=answers.names.trim()||answers.children.trim();
const loved=people?`Please watch over ${people}.`:answers.people.some(x=>x!=='Me')?'Hold her loved ones close, too.':'';
const gifts=answers.heart.map(x=>needs[x]);
const need=gifts.length?'Give her '+gifts.join(', ')+'.':'Give her rest for today and courage for tomorrow.';
return `Dear God,\n\nThank You for ${n}. ${season} ${need}\n\n${loved} ${answers.more.trim()?`Help her carry what weighs on her. `:''}Let her feel loved and draw closer to You.\n\nAmen.`;
}
function content(){
if(step===0)return openingPage(0);
if(step===1)return openingPage(1).replace('illustration-pack/cosmos.png','illustration-pack/grace-shell.png').replace('If you scroll for<br><strong>2 hours a day,</strong><br>that’s <em>14 hours a week.</em>','If you scroll for<br><strong>2 hours a day,</strong><br>that’ll be <em><span class="scroll-time-warning">10 years of your life</span> spent on social media.</em>').replace('For the woman with a full day and a full heart:<br>make a few of those minutes just you, God, and His Word.','').replace('One passage. A little breathing room.','').replace('</div><div class="actions">','<div class="christ-moment"><p class="cost-bridge">Let’s show you how to turn some of that time toward Christ.</p><img class="christ-art" src="illustration-pack/cosmos.png" alt=""></div></div><div class="actions">');
if(step===2)return layout('A different kind of scroll',`<h2>We’re going to help you spend less time scrolling social media and more time in the Bible.</h2><div class="demo demo-iphone" aria-label="iPhone 17 Pro Max app demonstration"><div class="demo-status" aria-hidden="true"><span>9:41</span><i class="demo-island"></i><span class="demo-system">▂▅▇ ▰</span></div><video src="onboarding-demo.webm" autoplay muted loop playsinline aria-label="Reading and saving a Bible passage on iPhone"></video><div class="demo-home" aria-hidden="true"></div></div>`,'A little space for you and His Word.');
if(step===4)return textPage('First, what should<br>we call you?', 'name', 'Your first name', 'given-name');
if(step===10)return textPage('Tell us something<br>that’s been<br>weighing you down.', 'more', 'In your own words…');
if(step===11)return textPage('Who’s someone in your life<br>you’d like to pray for?', 'names', 'My mom, Grace…');
if(data[step]){const q=data[step];return layout(answers.name.trim()?`A little about ${esc(answers.name.trim())}`:'A little about you',`${art(q.art)}<h2>${q.title}</h2><p class="sub">${q.sub}</p><div class="${step===9?'chips':step===7?'choices season-choices':'choices'}">${q.options.map((v,i)=>{const selected=q.multi?answers[q.key].includes(v):answers[q.key]===v;return `<button class="${step===9?'chip':'choice'} ${selected?'selected':''}" data-choice="${i}" aria-pressed="${selected}">${step===9?'':'<span class="radio" aria-hidden="true"></span>'}<span>${v}${step===12&&i===1?'<small>A gentle place to start</small>':''}</span></button>`}).join('')}</div><p class="limit" role="status"></p>`,q.foot,'Continue',true);}
if(step===13)return layout('A moment, just for you',`${art('faith-hands')}<h2>A prayer for you${answers.name.trim()?`,<br><em>${esc(answers.name.trim())}.</em>`:'.'}</h2><p class="sub">Your heart, held in prayer.</p><blockquote class="personal-prayer">${esc(prayer()).replace(/\n/g,'<br>')}</blockquote>`,'You can come back to these words.','Keep this prayer');
if(step===14)return layout('A gentle rhythm',`${art('reminder-bell')}<h2>When would you like<br>a moment with God?</h2><p class="sub">A quiet invitation to pause.</p><div class="reminder"><label class="switchrow"><span>Daily reminder<small>A quiet nudge, at your pace.</small></span><input type="checkbox" name="reminder" aria-label="Daily reminder" ${answers.reminder?'checked':''}></label>${reminderTime()}</div><section class="reminder-preview" aria-label="Example reminder"><p class="reminder-preview-label">A little preview</p><div class="notification"><div class="reminder-notification-top"><span><img src="assets/her-crown-app-icon.png" alt="" width="22" height="22">Her Crown</span><small>now</small></div><h3>A moment in the Word?</h3><p>Set the scroll aside. There’s a little peace waiting for you.</p></div></section>`,'You can change this anytime in Settings.','Save my choice');
return layout('Your little space is ready',`${art('dove')}<h2>You don’t have to<br>begin perfectly.</h2><p class="sub">Just begin as you are${answers.name.trim()?', '+esc(answers.name.trim()):''}. One passage. One prayer. A little room for God.</p><p class="letter-copy">Your prayer is saved on this device.</p><button class="secondary" data-action="download">Save a copy of my prayer</button>`,'Come as you are.',onFinish?'Open my Bible':'Begin again','', 'restart');
}
function reminderTime(){return `<div class="reminder-time-row"><label for="reminder-time">Remind me at</label><input type="time" id="reminder-time" name="time" value="${esc(answers.time)}"></div>`;}
function textPage(title,key,placeholder,autocomplete='off'){
return layout(key==='name'?'Let’s make this feel like you':'In your own words',`<div class="conversation"><div class="onboarding-heading"><h2>${title}</h2><img src="illustration-pack/${key==='name'?'journal':key==='more'?'rest-stones':'prayer-envelope'}.png" alt=""></div></div><div class="input-dock"><label class="sr-only" for="answer">${placeholder}</label><input id="answer" name="${key}" autocomplete="${autocomplete}" ${key==='name'?'autocapitalize="words"':''} enterkeyhint="next" maxlength="${key==='name'?24:key==='more'?100:60}" value="${esc(answers[key])}" placeholder="${placeholder}"><button data-action="next" aria-label="Continue">→</button></div>`,'','',true).replace('new-screen step-', 'new-screen text-screen step-');
}
function lead(){const text=step===4?'Now let’s build a Bible experience that’s for you.\n\nWe’ll ask a few questions to shape your own For You page.':acknowledgement;return text?`<p class="question-lead">${esc(text).replace(/\n\n/g,'<br><br>')}</p>`:'';}
function responseFor(previous){
const name=answers.name.trim();
const list=a=>a.length>1?a.slice(0,-1).join(', ')+' and '+a.at(-1):a[0];
if(previous===4&&name)return `It’s lovely to meet you, ${name}.`;
if(previous===5&&answers.comparison)return answers.comparison==='Social media'?'Thank you for being honest. We can begin with one small moment.':answers.comparison==='The Bible'?'Let’s make space for the time you already love in the Word.':'Let’s find a rhythm that feels right for you.';
if(previous===7&&answers.season.length&&!answers.season.includes('Prefer not to say'))return answers.season.includes('Motherhood')&&answers.season.includes('Single')?'Being single and raising children can hold so much. This space is for you, too.':answers.season.includes('Motherhood')?'You’re making room for God in the midst of motherhood. There’s room for you here, too.':answers.season.includes('Separated or divorced')?'After a separation, even familiar things can feel different. We’ll begin gently.':answers.season.includes('Married')?'Let’s make room for your own walk with God alongside married life.':answers.season.includes('Dating')?'As you make room for love, let’s make room for your faith, too.':'In this season of being single, this can be a little space for your faith.';
if(previous===8&&answers.familiarity)return answers.familiarity==='Just starting'?'You don’t have to know where everything is to begin.':answers.familiarity==='I know a little'?'There’s room to grow, one passage at a time.':'Let’s make space to go a little deeper.';
if(previous===9&&answers.heart.length)return `You’re bringing ${list(answers.heart.map(x=>x.toLowerCase()))} into this space. There’s room for all of it.`;
if(previous===10&&answers.more.trim())return `Thank you for sharing that${name?', '+name:''}. We’ll bring your words into your prayer.`;
if(previous===11&&answers.names.trim())return `We’ll lift up ${answers.names.trim()} in your prayer, too.`;
if(previous===12&&answers.pace)return answers.pace==='No set goal'?'No clock to keep up with. Just a little space for God.':`${answers.pace} is a gentle place to begin. Let’s make those moments yours.`;
return '';
}
function layout(kicker,body,foot,label='Continue',skip=false,action='next'){
body=body.replace(/<img class="question-art"([^>]*?)><h2>([\s\S]*?)<\/h2>/,(_,attrs,title)=>'<div class="onboarding-heading"><h2>'+title+'</h2><img'+attrs+'></div>');
if(answers.name.trim()&&([5,7,8,9,10,11,12,14].includes(step)))body=body.replace(/<h2>([\s\S]*?)<\/h2>/,(_,title)=>'<h2>'+esc(answers.name.trim())+', '+title.charAt(0).toLowerCase()+title.slice(1)+'</h2>');
const index=flow.indexOf(step),segment=Math.floor(index/(flow.length-1)*7);
return `<section class="screen new-screen step-${step} ${step===13?'prayer-screen':step===14?'reminder-screen':''}"><div class="top"><button class="iconbtn" data-action="back" aria-label="Back"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 19-7-7 7-7M19 12H5"/></svg></button><span class="kicker" style="margin:0">A moment for you</span>${skip?'<button class="textbtn" data-action="next">Skip</button>':'<span class="top-spacer"></span>'}</div><div class="progress" role="progressbar" aria-label="Onboarding" aria-valuemin="1" aria-valuemax="${flow.length}" aria-valuenow="${index+1}">${Array.from({length:8},(_,i)=>`<i class="${i<=segment?'on':''}"></i>`).join('')}</div><div class="content">${lead()}<div class="question-body">${body}</div></div><div class="actions">${btn(label,action)}<p class="footnote">${foot}</p></div></section>`;
}
function render(){root.innerHTML=content();root.scrollTop=0;window.scrollTo(0,0);mountOnboardingMotion(root,step);const heading=root.querySelector('h2');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});}
root.addEventListener('input',e=>{if(!active)return;if(e.target.name&&e.target.type!=='checkbox')answers[e.target.name]=e.target.value;});
root.addEventListener('change',e=>{if(!active)return;if(e.target.name==='reminder'){answers.reminder=e.target.checked;e.target.focus();}});
root.addEventListener('click',async e=>{if(!active)return;const choice=e.target.closest('[data-choice]');if(choice){const q=data[step],v=q.options[+choice.dataset.choice];if(q.multi){const a=answers[q.key];if(q.key==='season'){if(v==='Prefer not to say'){const was=a.includes(v);a.splice(0,a.length);if(was)a.push(v);}else{const privateIndex=a.indexOf('Prefer not to say');if(privateIndex>=0)a.splice(privateIndex,1);}}const i=a.indexOf(v);if(i>=0)a.splice(i,1);else if(step===9&&a.length===3){root.querySelector('.limit').textContent='Choose up to three. Tap one again to make room.';return}else a.push(v);}else answers[q.key]=v;root.querySelectorAll('[data-choice]').forEach(button=>{const value=q.options[+button.dataset.choice];const selected=q.multi?answers[q.key].includes(value):answers[q.key]===value;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});root.querySelector('.limit').textContent='';return;}
const trigger=e.target.closest('[data-action]');const a=trigger?.dataset.action;if(!a||trigger.closest('[inert]')||trigger.disabled)return;if(a==='next')answers.name=answers.name.trim().replace(/^\p{L}/u,c=>c.toLocaleUpperCase());if(a==='back'){acknowledgement='';step=flow[Math.max(0,flow.indexOf(step)-1)];render();return}if(a==='restart'&&onFinish){active=false;onFinish(answers,false);return}if(a==='restart'){step=0;render();return}if(a==='guest'&&onFinish){active=false;onFinish(answers,true);return}if(a==='guest'){try{localStorage.setItem('her-crown-onboarding-prayer-v2',prayer())}catch{}step=15;render();return}if(a==='download'){download();return}if(a==='next'){acknowledgement=e.target.closest('.textbtn')?'':responseFor(step);if(step===13){try{localStorage.setItem('her-crown-onboarding-prayer-v2',prayer())}catch{}}if(step===14){try{localStorage.setItem('her-crown-onboarding-reminder-v2',JSON.stringify({time:answers.time,enabled:answers.reminder}));}catch{}}if(step===14&&answers.reminder){try{localStorage.setItem('her-crown-onboarding-reminder-v2',JSON.stringify({time:answers.time,enabled:true}));}catch{}if('Notification'in window&&Notification.permission==='default')await Notification.requestPermission();}step=flow[Math.min(flow.length-1,flow.indexOf(step)+1)];render();}});
function contentForChoice(){return content()}
function download(){const url=URL.createObjectURL(new Blob([prayer()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='A-prayer-for-you.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

root.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Enter'&&e.target.matches('.input-dock input')){e.preventDefault();root.querySelector('.input-dock [data-action=next]').click();}});
function viewport(){if(!active)return;const v=window.visualViewport;document.documentElement.style.setProperty('--visible-height',`${v?.height||innerHeight}px`);window.scrollTo(0,0);}
window.visualViewport?.addEventListener('resize',viewport);window.addEventListener('resize',viewport);viewport();

return {show(){active=true;if(root.querySelector('.screen'))return;viewport();render()},hide(){active=false;resetOnboardingMotion();},restart(){resetOnboardingMotion();acknowledgement='';step=0;active=true;viewport();render()}};
}
if(!document.documentElement.hasAttribute('data-integrated-onboarding'))createPersonalOnboarding(document.querySelector('#app')).show();
